// ============================================================
// Rule: MS_Suspicious UserAgent Login Detected
// Vendor: Microsoft EntraID
// Objective:
// Detect activity associated with MS_Suspicious UserAgent Login Detected.
// Severity: SEV_030_MEDIUM
// Category: CREDENTIAL_ACCESS
// ============================================================
// SANITIZED: Environment-specific values replaced with generic placeholders.
// MITRE ATT&CK:
// Tactic: TA0006 - Credential Access
// Technique: T1110.003 - Brute Force: Password Spraying

dataset = msft_azure_raw
| alter
    // Extract main fields from log properties
    Agente = properties -> userAgent,
    Usuario = properties -> userPrincipalName,
    userPrincipalName = properties -> userPrincipalName,
    userDisplayName = properties -> userDisplayName,
    userId = properties -> userId,
    ipAddress = properties -> ipAddress,
    city = properties -> location.city,
    state = properties -> location.state,
    countryOrRegion = properties -> location.countryOrRegion,
    geoCoordinates = properties -> location.geoCoordinates,
    appDisplayName = properties -> appDisplayName,
    resultType = properties -> resultType,
    resultDescription = properties -> resultDescription,
    riskEventType = properties -> riskEventType

    // Filter by suspicious or automated User-Agent values
| filter (
    Agente contains "curl" or
    Agente contains "wget" or
    Agente contains "python-requests" or
    Agente contains "python-urllib" or
    Agente contains "hydra" or
    Agente contains "go-http-client" or
    Agente contains "apache-httpclient" or
    Agente contains "java" or
    Agente contains "nikto" or
    Agente contains "sqlmap" or
    Agente contains "owasp zap" or
    Agente contains "dirbuster" or
    Agente contains "postmanruntime" or
    Agente contains "libwww-perl" or
    Agente contains "winhttp.winhttprequest" or
    Agente contains "mechanize"
)
//| filter resultType = "Success"
    // Select fields relevant for investigation
| fields Agente, properties, userPrincipalName, userDisplayName, appDisplayName, ipAddress, city, state, countryOrRegion, resultType, resultDescription

    //App Exceptions

| filter (appDisplayName not in ("""<INTERNAL_APPLICATION_2>""", """<INTERNAL_APPLICATION_3>""", """Check Point Cloud Security Platform - Emails V2""","Viva Engage", "<INTERNAL_APPLICATION_4>","vRx SAML","<INTERNAL_APPLICATION_5>"))

    // Users Exceptions

| filter (userPrincipalName not in ("""<USER_EMAIL_1>""", """<USER_EMAIL_2>""", """<USER_EMAIL_3>""","<USER_EMAIL_4>"))
